// src/hooks/useAttendanceData.js
import { useEffect, useState } from "react";

const useAttendanceData = (selectedDate) => {
  const [calendarData, setCalendarData] = useState({});
  const [barChartData, setBarChartData] = useState([
    { name: "기획", value: 0 },
    { name: "디자인", value: 0 },
    { name: "개발", value: 0 },
    { name: "기타", value: 0 },
  ]);
  const [dailyTotal, setDailyTotal] = useState(0);
  const [monthlyTotal, setMonthlyTotal] = useState(0);
  const [monthPieData, setMonthPieData] = useState([]);
  const [activeMonth, setActiveMonth] = useState(selectedDate.getMonth() + 1);

  const dateKey = selectedDate.toISOString().split("T")[0];

  // 날짜 변경 시 데이터 불러오기
  useEffect(() => {
    const saved = localStorage.getItem(dateKey);
    if (saved) {
      const parsed = JSON.parse(saved);
      setBarChartData(parsed);
    } else {
      setBarChartData([
        { name: "기획", value: 0 },
        { name: "디자인", value: 0 },
        { name: "개발", value: 0 },
        { name: "기타", value: 0 },
      ]);
    }
  }, [selectedDate]);

  // 입력 변경 시 저장 및 총합 계산
  useEffect(() => {
    localStorage.setItem(dateKey, JSON.stringify(barChartData));

    const total = barChartData.reduce((sum, item) => sum + Number(item.value), 0);
    setDailyTotal(total);

    // 달 전체 데이터를 다시 계산
    const month = selectedDate.getMonth();
    const year = selectedDate.getFullYear();
    const newCalendar = {};
    let monthSum = 0;
    const projectSums = {};

    for (let i = 1; i <= 31; i++) {
      const day = new Date(year, month, i);
      if (day.getMonth() !== month) continue;

      const key = day.toISOString().split("T")[0];
      const dayData = JSON.parse(localStorage.getItem(key));
      if (dayData) {
        const dayTotal = dayData.reduce((sum, item) => sum + Number(item.value), 0);
        newCalendar[key] = { total: dayTotal };
        monthSum += dayTotal;

        dayData.forEach((item) => {
          projectSums[item.name] = (projectSums[item.name] || 0) + Number(item.value);
        });
      }
    }

    setCalendarData(newCalendar);
    setMonthlyTotal(monthSum);

    const pieData = Object.entries(projectSums).map(([name, value]) => ({
      name,
      value,
    }));
    setMonthPieData(pieData);
    setActiveMonth(month + 1);
  }, [barChartData]);

  const handleTimeChange = (index, newValue) => {
    const updated = [...barChartData];
    updated[index].value = Number(newValue);
    setBarChartData(updated);
  };

  const getTopProjectSummary = () => {
    if (!monthPieData.length) return "이번 달 근무 기록이 없습니다.";

    const sorted = [...monthPieData].sort((a, b) => b.value - a.value);
    const total = sorted.reduce((sum, item) => sum + item.value, 0);
    const topProject = sorted[0];
    const percentages = sorted.map(
      (proj) => `${proj.name} 프로젝트는 ${((proj.value / total) * 100).toFixed(1)}%`
    );

    return `${activeMonth}월에 가장 많은 기여를 한 프로젝트는 ${topProject.name}입니다. ${percentages.join(", ")}입니다.`;
  };

  return {
    calendarData,
    barChartData,
    pieChartData: monthPieData,
    dailyTotal,
    monthlyTotal,
    monthPieData,
    activeMonth,
    handleTimeChange,
    getTopProjectSummary,
  };
};

export default useAttendanceData;
